#!/usr/bin/env node
// Headless Llama 3.2 1B per-layer parity harness. Boots vite + puppeteer,
// uploads the model safetensors + the reference dump via file chooser, runs
// the requested subset of parity stages, and reports pass/fail per stage.
//
// The reference dump is generated by scripts/llama_reference_dump.py.
//
// Usage:
//   node scripts/llama-bench.mjs --model ext/llama-3.2-1b.safetensors \
//     --ref ext/llama_ref_dump.safetensors
//     [--backend workers]      # workers | webgpu | wasm
//     [--memory 2000]          # heap MB
//     [--layers 0,15]          # comma indices or 'all'
//     [--timeout 300000]       # ms
//     [--headed]               # show browser
//     [--json]                 # print result envelope on stdout
//
// Exit codes:
//   0  all stages match
//   1  bad args
//   2  page error / thrown exception
//   3  timeout
//   4  one or more stages diverged

import { spawn } from "node:child_process";
import { createServer } from "node:net";
import { existsSync } from "node:fs";
import { setTimeout as sleep } from "node:timers/promises";
import path from "node:path";

function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith("--")) { out._.push(a); continue; }
    const key = a.slice(2);
    const next = argv[i + 1];
    if (next === undefined || next.startsWith("--")) {
      out[key] = true;
    } else {
      out[key] = next;
      i++;
    }
  }
  return out;
}

async function pickFreePort() {
  return await new Promise((resolve, reject) => {
    const srv = createServer();
    srv.unref();
    srv.on("error", reject);
    srv.listen(0, () => {
      const port = srv.address().port;
      srv.close(() => resolve(port));
    });
  });
}

async function waitForServer(url, timeoutMs) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const r = await fetch(url);
      if (r.ok) return;
    } catch {}
    await sleep(200);
  }
  throw new Error(`server not up at ${url} within ${timeoutMs}ms`);
}

function startVite(port) {
  const proc = spawn(
    "npx",
    ["vite", "--port", String(port), "--strictPort", "--clearScreen", "false"],
    { stdio: ["ignore", "pipe", "pipe"], shell: true },
  );
  proc.stdout.on("data", (d) => process.stderr.write(`[vite] ${d}`));
  proc.stderr.on("data", (d) => process.stderr.write(`[vite] ${d}`));
  return proc;
}

function killTree(child) {
  if (!child || child.killed) return;
  if (process.platform === "win32" && child.pid) {
    try { spawn("taskkill", ["/pid", String(child.pid), "/T", "/F"], { stdio: "ignore" }); }
    catch { child.kill(); }
  } else {
    child.kill();
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.model || !args.ref) {
    console.error("--model <path> and --ref <path> are required.");
    console.error("run with --help for full usage.");
    process.exit(1);
  }
  const modelPath = path.resolve(String(args.model));
  const refPath = path.resolve(String(args.ref));
  if (!existsSync(modelPath)) { console.error(`model not found: ${modelPath}`); process.exit(1); }
  if (!existsSync(refPath)) { console.error(`ref not found: ${refPath}`); process.exit(1); }

  const backend = args.backend ?? "workers";
  const memory = args.memory ?? "2000";
  const layers = args.layers ?? "0,15";
  const timeoutMs = Number(args.timeout ?? 300000);

  console.error(`[bench] model   = ${modelPath}`);
  console.error(`[bench] ref     = ${refPath}`);
  console.error(`[bench] backend = ${backend}  memory = ${memory}MB  layers = ${layers}`);

  const port = await pickFreePort();
  const vite = startVite(port);
  const cleanup = () => killTree(vite);
  process.on("exit", cleanup);
  process.on("SIGINT", () => { cleanup(); process.exit(130); });
  process.on("SIGTERM", () => { cleanup(); process.exit(143); });

  await waitForServer(`http://localhost:${port}/llama-bench.html`, 30000);

  const { default: puppeteer } = await import("puppeteer");
  const browser = await puppeteer.launch({
    headless: args.headed ? false : true,
    args: [
      "--enable-unsafe-webgpu",
      "--enable-features=Vulkan",
      "--use-vulkan=swiftshader",
      "--enable-webgpu-developer-features",
      // Extend V8's max old space so we can hold a 2.5 GB ArrayBuffer plus
      // decompressed subsets during parsePartialSafetensors.
      "--js-flags=--max-old-space-size=8192",
    ],
    // Give Chromium some breathing room for the big model buffer.
    protocolTimeout: timeoutMs,
  });
  const page = await browser.newPage();

  let result = null;
  let error = null;
  page.on("pageerror", (err) => { error = err.message; });
  page.on("console", (msg) => {
    const text = msg.text();
    if (text.startsWith("__RESULT__")) {
      try { result = JSON.parse(text.slice("__RESULT__".length)); } catch (e) { error = String(e); }
    } else if (text.startsWith("__ERROR__")) {
      error = text.slice("__ERROR__".length);
    } else if (text.startsWith("[bench] ")) {
      process.stderr.write(text + "\n");
    } else if (msg.type() === "error" || msg.type() === "warning") {
      process.stderr.write(`[browser ${msg.type()}] ${text}\n`);
    }
  });

  const url = new URL(`http://localhost:${port}/llama-bench.html`);
  url.searchParams.set("backend", backend);
  url.searchParams.set("memory", String(memory));
  url.searchParams.set("layers", String(layers));
  await page.goto(url.toString(), { waitUntil: "load" });

  await page.waitForFunction(
    () => document.getElementById("status")?.textContent === "await-ref",
    { timeout: 30000 },
  );
  const refInput = await page.$("#ref-input");
  if (!refInput) throw new Error("#ref-input not found");
  await refInput.uploadFile(refPath);

  await page.waitForFunction(
    () => document.getElementById("status")?.textContent === "await-model",
    { timeout: 60000 },
  );
  const modelInput = await page.$("#model-input");
  if (!modelInput) throw new Error("#model-input not found");
  await modelInput.uploadFile(modelPath);

  const deadline = Date.now() + timeoutMs;
  while (!result && !error && Date.now() < deadline) {
    await sleep(500);
  }

  await browser.close();
  killTree(vite);

  if (error) { console.error(`[bench] FAIL: ${error}`); process.exit(2); }
  if (!result) { console.error(`[bench] TIMEOUT after ${timeoutMs}ms`); process.exit(3); }

  if (args.json) {
    console.log(JSON.stringify(result));
  } else {
    console.error("");
    console.error(`[bench] ${result.passed}/${result.total} stages match`);
    for (const r of result.results) {
      const mark = r.ok ? "OK" : "FAIL";
      console.error(
        `  ${r.stage.padEnd(14)} diff=${r.diff.toExponential(3)}  cos=${r.cos.toFixed(6)}  ${mark}`,
      );
    }
  }
  process.exit(result.passed === result.total ? 0 : 4);
}

main().catch((e) => {
  console.error(`[bench] fatal: ${e.stack ?? e.message ?? e}`);
  process.exit(2);
});
